// D/ST streaming recommendations (backlog item 14): rank the available
// team defenses for a given week by how generous their opponent's offense
// has been to opposing defenses over completed weeks.
//
// Data is generated by `npm run fetch:matchups` (scripts/buildMatchupRatings.ts)
// from Sleeper's free weekly team-defense stats, scored with the standard
// D/ST scoring documented in defenseGenerosity.2026.json. Rank 1 = the
// offense gives up the most fantasy points to opposing defenses (the best
// streaming target). Implemented from TraderApe's own data; the weekly
// "which defense do I stream" question is the FantasyPros/Yahoo DST-streamer
// use case, priced here on our own numbers.

import scheduleJson from '@/data/nflSchedule.2026.json';
import generosityJson from '@/data/defenseGenerosity.2026.json';

export type DstMatchupLabel = 'favorable' | 'neutral' | 'tough';

export interface DstMatchup {
  /** The streaming defense's canonical abbreviation. */
  team: string;
  /** This week's opponent (canonical abbreviation). */
  opponent: string;
  /** Avg fantasy pts the opponent's offense allowed to opposing defenses. */
  avgAllowed: number;
  /** 1 = most generous to opposing defenses (best streaming target). */
  rank: number;
  label: DstMatchupLabel;
  /** The defense's own avg fantasy points over completed weeks. */
  ownAvg: number;
}

interface ScheduleFile {
  season: number;
  weeks: Record<string, Array<[string, string]>>;
  generatedAt: string;
}

interface GenerosityFile {
  season: number;
  weeks: [number, number];
  scoring: string;
  teams: Record<
    string,
    { generosityAvg: number; generosityRank: number; ownAvg: number }
  >;
  generatedAt: string;
}

// JSON imports widen tuples to arrays; assert through unknown so the
// tuple types hold.
const SCHEDULE = scheduleJson as unknown as ScheduleFile;
const GENEROSITY = generosityJson as unknown as GenerosityFile;

function labelFor(rank: number): DstMatchupLabel {
  // Same cutoffs as the weekly skill-position matchup rating.
  if (rank <= 10) return 'favorable';
  if (rank >= 23) return 'tough';
  return 'neutral';
}

/** First and last completed week that fed the generosity averages. */
export function generosityWeeksRange(): [number, number] {
  return GENEROSITY.weeks;
}

/**
 * This week's streaming matchup for one defense: the opponent from the
 * bundled schedule plus the opponent's generosity rating. Null when the
 * defense has no game that week (bye) or no generosity data.
 */
export function getDstMatchup(
  team: string | null | undefined,
  week: number | undefined,
  schedule: ScheduleFile = SCHEDULE,
  generosity: GenerosityFile = GENEROSITY,
): DstMatchup | null {
  if (!team || week === undefined) return null;
  const games = schedule.weeks[String(week)];
  const game = games?.find(([h, a]) => h === team || a === team);
  if (!game) return null;
  const opponent = game[0] === team ? game[1] : game[0];
  const entry = generosity.teams[opponent];
  if (!entry) return null;
  return {
    team,
    opponent,
    avgAllowed: entry.generosityAvg,
    rank: entry.generosityRank,
    label: labelFor(entry.generosityRank),
    ownAvg: generosity.teams[team]?.ownAvg ?? 0,
  };
}

/**
 * Rank the defenses available in `week` for streaming: every NFL defense
 * with a game that week and no generosity data gaps, excluding the ones
 * already rostered. Ordered by opponent generosity (best target first),
 * ties broken by the defense's own completed-week scoring average.
 */
export function rankDstStreamers(
  week: number | undefined,
  rosteredDefenses: ReadonlySet<string>,
  limit = 5,
  schedule: ScheduleFile = SCHEDULE,
  generosity: GenerosityFile = GENEROSITY,
): DstMatchup[] {
  if (week === undefined) return [];
  const seen = new Set<string>();
  const entries: DstMatchup[] = [];
  for (const [h, a] of schedule.weeks[String(week)] ?? []) {
    for (const team of [h, a]) {
      if (seen.has(team)) continue;
      seen.add(team);
      if (rosteredDefenses.has(team)) continue;
      const matchup = getDstMatchup(team, week, schedule, generosity);
      if (matchup) entries.push(matchup);
    }
  }
  entries.sort((x, y) => x.rank - y.rank || y.ownAvg - x.ownAvg);
  return entries.slice(0, Math.max(0, limit));
}
